-- Conservacion de datos originales. Ejecutar completo en REGOVA_BD.
-- No reemplaza la migracion al modelo operacional ni conecta FastAPI.
BEGIN;
SET LOCAL standard_conforming_strings=on;
DO $$ BEGIN IF current_database()<>'REGOVA_BD' THEN RAISE EXCEPTION 'Conectarse a REGOVA_BD'; END IF; END $$;
CREATE SCHEMA IF NOT EXISTS regova_legacy;
CREATE TABLE IF NOT EXISTS regova_legacy.lotes (snapshot_sha256 text PRIMARY KEY, importado_en timestamptz NOT NULL DEFAULT current_timestamp, resumen jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS regova_legacy.analisis (snapshot_sha256 text NOT NULL REFERENCES regova_legacy.lotes(snapshot_sha256), legacy_id bigint NOT NULL, fila_original jsonb NOT NULL, result_json_original text NOT NULL, rol_autor_propuesto text NOT NULL CHECK(rol_autor_propuesto IN ('administrador','supervisor')), autoria_asignada_para_prueba boolean NOT NULL CHECK(autoria_asignada_para_prueba), PRIMARY KEY(snapshot_sha256,legacy_id));
CREATE TABLE IF NOT EXISTS regova_legacy.archivos (snapshot_sha256 text NOT NULL REFERENCES regova_legacy.lotes(snapshot_sha256), clave text NOT NULL, legacy_id bigint, tipo text NOT NULL, sha256 text NOT NULL, bytes bigint NOT NULL, procedencia text NOT NULL, PRIMARY KEY(snapshot_sha256,clave));
DO $$ BEGIN IF (SELECT count(*) FROM regova_legacy.analisis WHERE snapshot_sha256='fe3e9a51f1271bf4be24df85722b82c867d492f677c601b25740d6f7532ad5b2')<>124 THEN RAISE EXCEPTION 'Cantidad de analisis importados incorrecta'; END IF; END $$;
COMMIT;
SELECT legacy_id,rol_autor_propuesto FROM regova_legacy.analisis WHERE snapshot_sha256='fe3e9a51f1271bf4be24df85722b82c867d492f677c601b25740d6f7532ad5b2' ORDER BY legacy_id;